/* HyperFormula-compatible local adapter for this static workbook bundle.
 * It implements the subset of the HyperFormula API used by assets/app.js:
 *   HyperFormula.buildFromSheets(...), getSheetId, getCellValue, setCellContents.
 * It evaluates common Excel formulas used in the bundled workbook data.
 */
(function(global){
  function colToIdx(col){ col=String(col).replace(/\$/g,'').toUpperCase(); let n=0; for(const ch of col){ n=n*26 + ch.charCodeAt(0)-64; } return n-1; }
  function idxToCol(n){ let s=''; n++; while(n>0){ let r=(n-1)%26; s=String.fromCharCode(65+r)+s; n=Math.floor((n-1)/26); } return s; }
  function parseA1(a1){ const m=String(a1).replace(/\$/g,'').match(/^([A-Z]+)(\d+)$/i); if(!m) return null; return {col:colToIdx(m[1]), row:parseInt(m[2],10)-1}; }
  function isErr(v){ return v && typeof v==='object' && v.__hfErr; }
  function Err(msg){ return {__hfErr:true, msg:msg||'#ERROR!', valueOf:function(){return NaN;}, toString:function(){return this.msg;}}; }
  function isBlank(v){ return v==null || v===''; }
  function flat(a){ if(!Array.isArray(a)) return [a]; const out=[]; (function rec(x){ Array.isArray(x)?x.forEach(rec):out.push(x); })(a); return out; }
  function toNum(v){ if(isErr(v)) return NaN; if(Array.isArray(v)) return toNum(flat(v)[0]); if(v===true) return 1; if(v===false || v==='' || v==null) return 0; const n=Number(v); return Number.isFinite(n)?n:NaN; }
  function cmpVal(v){ if(Array.isArray(v)) v=flat(v)[0]; if(isErr(v)) return NaN; if(v==null) return ''; return v; }
  function truthy(v){ if(isErr(v)) return false; if(Array.isArray(v)) v=flat(v)[0]; if(typeof v==='boolean') return v; if(typeof v==='number') return v!==0 && !Number.isNaN(v); return v!=='' && v!=null && String(v).toLowerCase()!=='false'; }
  function exact(a,b){ a=cmpVal(a); b=cmpVal(b); if(typeof a==='number' || typeof b==='number') return toNum(a)===toNum(b); return String(a)===String(b); }
  function makeRegexText(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\\\*/g,'.*').replace(/\\\?/g,'.'); }
  class LocalHF{
    constructor(sheets){
      this.sheetNames=Object.keys(sheets||{});
      this.nameToId={}; this.idToName={};
      this.sheets={}; this.cache=new Map(); this.compiled=new Map(); this.visiting=new Set();
      this.sheetNames.forEach((name,i)=>{ this.nameToId[name]=i; this.idToName[i]=name; this.sheets[name]=(sheets[name]||[]).map(r=>(r||[]).slice()); });
    }
    static buildFromSheets(sheets, opts){ return new LocalHF(sheets, opts); }
    getSheetId(name){ return this.nameToId[name]; }
    _name(sheet){ if(typeof sheet==='number') return this.idToName[sheet]; return sheet; }
    _key(sheet,row,col){ return this._name(sheet)+'!'+row+','+col; }
    _raw(sheet,row,col){ sheet=this._name(sheet); const sh=this.sheets[sheet]; if(!sh || row<0 || col<0) return ''; const r=sh[row]; return r && col<r.length && r[col]!=null ? r[col] : ''; }
    getCellValue(addr){ try{ return this._evalCell(addr.sheet, addr.row, addr.col); }catch(e){ return Err(e && e.message || '#ERROR!'); } }
    setCellContents(addr, matrix){ const sheet=this._name(addr.sheet); if(!this.sheets[sheet]) this.sheets[sheet]=[]; const rows=matrix||[[null]]; for(let r=0;r<rows.length;r++){ const rr=addr.row+r; if(!this.sheets[sheet][rr]) this.sheets[sheet][rr]=[]; for(let c=0;c<rows[r].length;c++){ this.sheets[sheet][rr][addr.col+c]=rows[r][c]; } } this.cache.clear(); }
    _evalCell(sheet,row,col){ sheet=this._name(sheet); const key=this._key(sheet,row,col); if(this.cache.has(key)) return this.cache.get(key); if(this.visiting.has(key)) return Err('#CYCLE!'); this.visiting.add(key); let raw=this._raw(sheet,row,col); let val; if(typeof raw==='string' && raw.startsWith('=')){ val=this._evalFormula(raw, sheet, row, col); } else { val=(raw==null?'':raw); } this.visiting.delete(key); this.cache.set(key,val); return val; }
    _range(sheet,a1,b1){ sheet=this._name(sheet); const a=parseA1(a1), b=parseA1(b1||a1); if(!a||!b) return Err('#REF!'); const r1=Math.min(a.row,b.row), r2=Math.max(a.row,b.row), c1=Math.min(a.col,b.col), c2=Math.max(a.col,b.col); const out=[]; for(let r=r1;r<=r2;r++){ const row=[]; for(let c=c1;c<=c2;c++) row.push(this._evalCell(sheet,r,c)); out.push(row); } return out; }
    _colRange(sheet,c1,c2){ sheet=this._name(sheet); const a=colToIdx(String(c1).replace(/\$/g,'')), b=colToIdx(String(c2||c1).replace(/\$/g,'')); const cc1=Math.min(a,b), cc2=Math.max(a,b); const maxRows=Math.max(1,(this.sheets[sheet]||[]).length); const out=[]; for(let r=0;r<maxRows;r++){ const row=[]; for(let c=cc1;c<=cc2;c++) row.push(this._evalCell(sheet,r,c)); out.push(row); } return out; }
    _cell(sheet,a1){ const a=parseA1(a1); if(!a) return Err('#REF!'); return this._evalCell(sheet,a.row,a.col); }
    _compile(expr, sheet, row, col){
      const cacheKey=sheet+'!'+row+','+col+'='+expr; if(this.compiled.has(cacheKey)) return this.compiled.get(cacheKey);
      let e=String(expr).slice(1);
      const strings=[]; e=e.replace(/"(?:[^"]|"")*"/g, m=>{ const i=strings.push(m)-1; return `¤${i}¤`; });
      const refs=[];
      const colRangeRe=/((?:'([^']+)'|([A-Za-z0-9_\u3040-\u30ff\u3400-\u9fff]+))!)?(\$?[A-Z]{1,3}):(\$?[A-Z]{1,3})(?!\$?\d)/g;
      e=e.replace(colRangeRe,(m,_sp,qs,bs,a,b)=>{ const sh=(qs||bs||sheet); const code=`COLRANGE(${JSON.stringify(sh)},${JSON.stringify(a.replace(/\$/g,'').toUpperCase())},${JSON.stringify(b.replace(/\$/g,'').toUpperCase())})`; const i=refs.push(code)-1; return `§${i}§`; });
      const refRe=/((?:'([^']+)'|([A-Za-z0-9_\u3040-\u30ff\u3400-\u9fff]+))!)?(\$?[A-Z]{1,3}\$?\d+)(?::(\$?[A-Z]{1,3}\$?\d+))?/g;
      e=e.replace(refRe,(m,_sp,qs,bs,a,b)=>{
        const sh=(qs||bs||sheet); const aa=a.replace(/\$/g,'').toUpperCase(); const bb=b?b.replace(/\$/g,'').toUpperCase():null;
        const code=bb?`RANGE(${JSON.stringify(sh)},${JSON.stringify(aa)},${JSON.stringify(bb)})`:`CELL(${JSON.stringify(sh)},${JSON.stringify(aa)})`;
        const i=refs.push(code)-1; return `§${i}§`;
      });
      // Excel -> JavaScript operators / names.
      e=e.replace(/<>/g,'!=').replace(/(?<![<>!])=(?!=)/g,'==').replace(/\^/g,'**').replace(/&(?!&)/g,'+');
      e=e.replace(/\bTRUE\b/gi,'true').replace(/\bFALSE\b/gi,'false');
      e=e.replace(/\b(iferror|ifs|if|and|or|not|index|match|max|min|abs|sqrt|int|rounddown|round|mod|countif|left|large|small|vlookup|text|log|row|column|isnumber|iserror|iseven)\s*\(/gi, m=>m.toUpperCase());
      // Excel permits omitted function arguments, e.g. INDEX(A1:B2,,2)
      let prev; do{ prev=e; e=e.replace(/,\s*,/g,',null,').replace(/\(\s*,/g,'(null,').replace(/,\s*\)/g,',null)'); }while(prev!==e);
      e=e.replace(/§(\d+)§/g,(_,i)=>refs[+i]);
      e=e.replace(/¤(\d+)¤/g,(_,i)=>{ const raw=strings[+i]; return JSON.stringify(raw.slice(1,-1).replace(/""/g,'"')); });
      this.compiled.set(cacheKey,e); return e;
    }
    _evalFormula(formula, sheet, row, col){
      const expr=this._compile(formula, sheet, row, col); const self=this;
      const ctx={
        CELL:(s,a)=>self._cell(s,a), RANGE:(s,a,b)=>self._range(s,a,b), COLRANGE:(s,a,b)=>self._colRange(s,a,b),
        IF:(c,t,f)=>truthy(c)?t:f,
        IFS:function(){ for(let i=0;i<arguments.length-1;i+=2){ if(truthy(arguments[i])) return arguments[i+1]; } return Err('#N/A'); },
        IFERROR:(v,alt)=> (isErr(v) || (typeof v==='number' && (Number.isNaN(v)||!Number.isFinite(v)))) ? alt : v,
        ISERROR:(v)=>isErr(v) || (typeof v==='number' && Number.isNaN(v)), ISNUMBER:(v)=>typeof v==='number' && Number.isFinite(v),
        AND:function(){ return Array.from(arguments).every(truthy); }, OR:function(){ return Array.from(arguments).some(truthy); }, NOT:(v)=>!truthy(v),
        MAX:function(){ const vals=flat(Array.from(arguments)).map(toNum).filter(Number.isFinite); return vals.length?Math.max(...vals):0; },
        MIN:function(){ const vals=flat(Array.from(arguments)).map(toNum).filter(Number.isFinite); return vals.length?Math.min(...vals):0; },
        ABS:(v)=>Math.abs(toNum(v)), SQRT:(v)=>Math.sqrt(toNum(v)), INT:(v)=>Math.floor(toNum(v)), MOD:(a,b)=>toNum(a)%toNum(b),
        ROUND:(v,d)=>{ d=d==null?0:toNum(d); const p=Math.pow(10,d); return Math.round(toNum(v)*p)/p; },
        ROUNDDOWN:(v,d)=>{ d=d==null?0:toNum(d); const p=Math.pow(10,d); const n=toNum(v)*p; return (n<0?Math.ceil(n):Math.floor(n))/p; },
        LOG:(v,b)=>Math.log(toNum(v))/Math.log(b==null?10:toNum(b)),
        INDEX:(arr,r,c)=>{ if(!Array.isArray(arr)) return (r==null||r===1)?arr:Err('#VALUE!'); r=(r==null?0:Math.trunc(toNum(r))); c=(c==null?0:Math.trunc(toNum(c))); const rows=arr.length, cols=(arr[0]||[]).length; if(r===0 && c===0) return arr; if(r===0){ if(c<1||c>cols) return Err('#REF!'); return arr.map(row=>[row[c-1]]); } if(c===0){ if(cols===1) return (arr[r-1]||[])[0] ?? Err('#REF!'); if(r<1||r>rows) return Err('#REF!'); return [arr[r-1]]; } if(r<1||r>rows||c<1||c>cols) return Err('#REF!'); return arr[r-1][c-1]; },
        MATCH:(lookup, arr, type)=>{ const vals=flat(arr); type=(type==null?1:toNum(type)); if(type===0){ for(let i=0;i<vals.length;i++) if(exact(vals[i],lookup)) return i+1; return Err('#N/A'); } if(type<0){ let best=-1; for(let i=0;i<vals.length;i++){ if(toNum(vals[i])>=toNum(lookup)) best=i; else break; } return best>=0?best+1:Err('#N/A'); } let best=-1; for(let i=0;i<vals.length;i++){ if(toNum(vals[i])<=toNum(lookup)) best=i; else break; } return best>=0?best+1:Err('#N/A'); },
        SMALL:(arr,k)=>{ const vals=flat(arr).map(toNum).filter(Number.isFinite).sort((a,b)=>a-b); k=Math.trunc(toNum(k)); return vals[k-1]??Err('#NUM!'); },
        LARGE:(arr,k)=>{ const vals=flat(arr).map(toNum).filter(Number.isFinite).sort((a,b)=>b-a); k=Math.trunc(toNum(k)); return vals[k-1]??Err('#NUM!'); },
        COUNTIF:(arr,crit)=>{ const vals=flat(arr); if(typeof crit==='string'){ const m=crit.match(/^(>=|<=|>|<|=|<>)(.*)$/); if(m){ const op=m[1], rhs=m[2]; return vals.filter(v=>{ if(op==='<>') return !exact(v,rhs); if(op==='=') return exact(v,rhs); const a=toNum(v), b=toNum(rhs); if(op==='>') return a>b; if(op==='<') return a<b; if(op==='>=') return a>=b; if(op==='<=') return a<=b; }).length; } if(/[?*]/.test(crit)){ const re=new RegExp('^'+makeRegexText(crit)+'$'); return vals.filter(v=>re.test(String(cmpVal(v)))).length; } } return vals.filter(v=>exact(v,crit)).length; },
        VLOOKUP:(lookup, table, idx, approx)=>{ idx=Math.trunc(toNum(idx)); if(!Array.isArray(table)||idx<1) return Err('#N/A'); for(const r of table){ if(exact(r[0],lookup)) return r[idx-1] ?? Err('#REF!'); } return Err('#N/A'); },
        LEFT:(s,n)=>String(cmpVal(s)).slice(0, n==null?1:Math.trunc(toNum(n))),
        TEXT:(v,fmt)=>{ if(typeof v==='number'){ const f=String(fmt); const m=f.match(/0\.(0+)/); if(m) return v.toFixed(m[1].length); if(f==='0') return String(Math.round(v)); } return String(cmpVal(v)); },
        ROW:(ref)=>{ if(ref==null) return row+1; if(Array.isArray(ref)) return 1; return row+1; },
        COLUMN:(ref)=>{ if(ref==null) return col+1; return col+1; },
        ISEVEN:(v)=>Math.trunc(toNum(v))%2===0,
      };
      try{ const fn=new Function('ctx','with(ctx){return ('+expr+');}'); const v=fn(ctx); return v==null?'':v; }catch(e){ return Err('#ERROR! '+(e&&e.message||'')); }
    }
  }
  LocalHF.version='local-compatible-1.0';
  global.HyperFormula=LocalHF;
})(typeof window!=='undefined'?window:globalThis);
